sp_widget.client_script:
api.controller = function($scope) {
	var c = this;
	//alert(c.data.pdfUrl);
	c.pdfUrl = $scope.data.pdfUrl;  // PDF URL (can be from sys_attachment or public URL)
	c.errorMessage = '';
	var docType = $scope.data.attachment.content_type;
 c.url = $scope.data.attachment.url;
	// Load PDF.js from CDN
	function loadPdfJs(callback) {
		if (window['pdfjsLib']) {
			callback();
			return;
		}
		var script = document.createElement('script');
		script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.7.570/pdf.min.js';
		script.onload = callback;
		document.head.appendChild(script);
	}

	c.loadPDF = function () {
	if (!c.pdfUrl) {
		c.errorMessage = "Please provide a PDF URL.";
		return;
	}
	c.errorMessage = '';

	loadPdfJs(() => {
		const url = c.pdfUrl;

		// Set worker path
		pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.7.570/pdf.worker.min.js';

		// Load the full PDF
		pdfjsLib.getDocument(url).promise.then(pdfDoc => {
			const container = document.getElementById('pdf-container');
			container.innerHTML = ''; // Clear previous content

			const scale = 1.2;

			// Render all pages
			for (let pageNum = 1; pageNum <= pdfDoc.numPages; pageNum++) {
				pdfDoc.getPage(pageNum).then(page => {
					const viewport = page.getViewport({ scale });

					const canvas = document.createElement('canvas');
					const context = canvas.getContext('2d');
					canvas.height = viewport.height;
					canvas.width = viewport.width;

					const renderContext = {
						canvasContext: context,
						viewport: viewport
					};

					// Append canvas first so order is preserved even with async rendering
					container.appendChild(canvas);
					page.render(renderContext);
				});
			}
		}).catch(err => {
			console.error("PDF load error:", err);
			c.errorMessage = "Could not load PDF.";
			$scope.$apply();
		});
	});
};


if(docType === "application/pdf"){
	c.section = 1;
	c.loadPDF();
} else {
	c.section = 2;
}

};

sp_widget.css:
.pdf-preview-widget {
	max-width: 800px;
	margin: auto;
  height: 900px:
}

#pdf-canvas {
	border: 1px solid #ccc;
	box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}
#pdf-scroll-wrapper {
	height: 600px; // Or any fixed height you want
	overflow-y: auto;
	border: 1px solid #ccc;
	padding: 10px;
	box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
	background: #fff;
}

#pdf-container canvas {
	display: block;
	margin: 1rem auto;
	max-width: 100%;
	box-shadow: 0 1px 5px rgba(0, 0, 0, 0.15);
}

#image-scroll-wrapper {
	height: 600px;
	overflow-y: auto;
	border: 1px solid #ccc;
	padding: 10px;
	background: #fafafa;
}

#image-container img {
	display: block;
	margin: 1rem auto;
	max-width: 100%;
	border: 1px solid #ddd;
	box-shadow: 0 1px 4px rgba(0, 0, 0, 0.15);
}

sp_widget.script:
(function () {
	// Use default sys_id if none provided
	var id = $sp.getParameter('attachment_id');
	console.log("Attachment - " + id);
	var inputSysId = gs.nil(id) ? '9e0f40f5470366107336e454116d4300' : id;
	data.pdfUrl = '/sys_attachment.do?sys_id='+ inputSysId;
	var attachment = new GlideRecord('sys_attachment');
	if (attachment.get(inputSysId)) {
		data.attachment = {
			sys_id: attachment.getValue('sys_id'),
			name: attachment.getValue('file_name'),
			content_type: attachment.getValue('content_type'),
			url: data.pdfUrl
		};
		data.trustedUrl = data.pdfUrl;
	} else {
		data.attachment = null;
	}

	if (input && input.action === 'load_script') {
		var uiScriptName = input.scriptName || 'JSZip'; // name of your UI Script
		var uiScript = new GlideRecord('sys_ui_script');
		uiScript.addQuery('name', uiScriptName);
		uiScript.query();
		if (uiScript.next()) {
			data.scriptCode = uiScript.getValue('script');
			data.scriptName = uiScriptName;
		} else {
			data.scriptCode = '';
			data.error = 'UI Script not found: ' + uiScriptName;
		}
	}
})();
